        Description: "A strong wind (20 miles per hour) blows around you in a 10-foot radius and moves with you, remaining centered on you. The wind deafens you and other creatures in its area. It extinguishes unprotected flames, hedges out vapor, gas, and fog, and makes the area difficult terrain for creatures other than you. Ranged weapon attacks that pass into or out of the wind have disadvantage. A creature that starts its turn in the wind must succeed on a Strength saving throw or be pushed 15 feet away from you.",
