        Description: "You create an intense pressure wave that sweeps out from you in a 30-foot cone. Each creature in that area must make a Constitution saving throw. On a failed save, a creature takes 6d6 force damage and is pushed up to 15 feet away from you or pulled up to 15 feet toward you. On a successful save, it takes half as much damage and isn't moved. In addition, unsecured objects that are completely within the cone are similarly pushed or pulled up to 15 feet.",
