        SpellSave: "Charisma",
        DamageType: "",
        DamageDice: [],
        ConditionsInflicted: [],
        Description: "You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a Charisma saving throw or be banished. If the target is native to the plane of existence you're on, you banish it to a harmless demiplane. While there, the target is incapacitated. It remains there until the spell ends, at which point it reappears in the space it left or the nearest unoccupied space. If the target is native to a different plane of existence than the one you're on, it is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears. Otherwise, it doesn't return.",
