        DamageType: "",
        DamageDice: [],
        ConditionsInflicted: [],
        Description: "You hide a chest and its contents on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component. The chest can contain up to 12 cubic feet of nonliving material. While the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica. After 60 days, there is a cumulative 5 percent chance per day that the spell's effect ends. The effect also ends if you cast this spell again, if the miniature chest is destroyed, or if you choose to end the spell as an action. If the spell ends while the larger chest is on the Ethereal Plane, it is irretrievably lost.",
        AtHigherLevels: "",
