        DamageDice: [],
        ConditionsInflicted: [],
        Description: "You call forth an aberrant spirit. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Aberrant Spirit stat block. When you cast the spell, choose Beholderkin, Slaad, or Star Spawn. The creature resembles an aberration of the chosen type, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends. The creature is friendly to you and your companions. In combat, it shares your initiative count but takes its turn immediately after yours. It obeys your verbal commands, and if you issue none, it takes the Dodge action and uses its movement to avoid danger.",
