        Source: "Xanathar's Guide to Everything",
        Classes: ["Warlock", "Wizard"],
        SpellAttackAttribute: "",
        SpellSave: "Charisma",
        DamageType: "",
        DamageDice: [],
        ConditionsInflicted: [],
        Description: "You utter foul words, summoning one demon from the chaos of the Abyss. You choose the demon's type, which must have a challenge rating of 5 or lower, such as a barlgura or a babau. The demon appears in an unoccupied space you can see within range. The demon disappears when it drops to 0 hit points or when the spell ends. Roll initiative for the demon, which has its own turns. When you summon it and on each of your turns thereafter, you can issue a verbal command to it. It obeys your commands if its challenge rating is equal to or less than your proficiency bonus. Otherwise, you must make a Charisma check contested by its Wisdom check to command it. If you lose the contest, the demon becomes uncontrolled and acts in its own interests. At the end of each of its turns, an uncontrolled demon makes a Charisma saving throw, ending the effect on itself on a success. As part of casting the spell, you can form a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. While the spell lasts, the summoned demon can't cross the circle or harm it, and it can't target anyone within it. Using the material component in this way consumes it.",
