        Type: "Evocation",
        Level: 5,
        CastingTime: "1 Action",
        Range: "60 ft.",
        Components: ["V", "S"],
        MaterialComponents: "",
        Duration: "Instantaneous",
        Concentration: false,
        Ritual: false,
        Source: "Player's Handbook",
        Classes: ["Bard", "Cleric", "Druid"],
        SpellAttackAttribute: "",
