        DamageType: "Fire",
        DamageDice: ["7d10"],
        ConditionsInflicted: [],
        Description: "A storm of roaring flames appears at a location you choose within range. The area consists of up to ten 10-foot cubes, which you can arrange as you wish. Each creature in the area must make a Dexterity saving throw, taking 7d10 fire damage on a failed save or half as much on a successful one. The fire damages objects in the area and ignites flammable objects that aren't being worn or carried. You can choose plant life in the area to be unaffected by the spell.",
