        Classes: ["Warlock", "Wizard"],
        SpellAttackAttribute: "",
        SpellSave: "Wisdom",
        DamageType: "",
        DamageDice: [],
        ConditionsInflicted: ["Restrained"],
        Description: "You create magical restraints to hold a creature you can see within range. The target must succeed on a Wisdom saving throw or be imprisoned by one of five methods: burial, chaining, hedged prison, minimus containment, or slumber. Each method uses a different special material component and has its own restrictions and effects. While imprisoned, the target does not need to breathe, eat, or drink, and it does not age. Divination spells cannot locate or perceive the target. The spell lasts until dispelled or ended by the specific conditions of the chosen imprisonment method.",
