        Description: "A shimmering, multicolored plane of light forms a vertical opaque wall up to 90 feet long, 30 feet high, and 1 inch thick, or a sphere up to 30 feet in diameter centered on a point you can see. The wall consists of seven layers, each a different color, with distinct magical properties. A creature that attempts to reach or pass through the wall must make a Dexterity saving throw or be affected by the layer it encounters. The layers can inflict damage, blindness, restraint, petrification, or other effects. Each layer can be destroyed by a specific type of damage or magical effect, in the correct order, from red through violet. The wall emits bright light out to 100 feet and dim light for an additional 100 feet.",
